contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount of wei to deposit into c
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // record c's balance before deposit
        uint cBalanceBeforeDeposit = address(c).balance;

        // perform deposit of `depositAmount` into c as msg.sender == this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record c's balance immediately after deposit
        uint cBalanceAfterDeposit = address(c).balance;

        // Now attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record c's balance after withdraw attempt
        uint cBalanceAfterWithdraw = address(c).balance;

        // General rule: after depositing and then calling withdrawAll (regardless of revert),
        // C's balance does not increase compared to its post-deposit balance.
        assert(cBalanceAfterWithdraw <= cBalanceAfterDeposit);
    }

    // allow receiving Ether so withdrawAll can send funds here
    receive() external payable {}
}

